package com.example.jobfinderapp.activities;
import android.content.Intent;import android.os.Bundle;import android.text.*;import android.view.View;import android.widget.*;import androidx.appcompat.app.*;import androidx.recyclerview.widget.*;import com.example.jobfinderapp.R;import com.example.jobfinderapp.adapters.ManageApplicantsAdapter;import com.example.jobfinderapp.database.DBHelper;import com.example.jobfinderapp.models.Company;import com.example.jobfinderapp.models.User;import com.example.jobfinderapp.utils.UserSession;import com.google.android.material.appbar.MaterialToolbar;import java.util.*;
public class ManageApplicantsActivity extends AppCompatActivity{private DBHelper db;private int companyId;private List<Map<String,Object>> rows=new ArrayList<>();private ManageApplicantsAdapter adapter;private String status="";private EditText search;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_manage_applicants);db=DBHelper.getInstance(this);UserSession s=new UserSession(this);int uid=s.isLoggedIn()?s.getUserId():-1;User u=uid>0?db.getUserById(uid):null;Company c=uid>0?db.getCompanyByUserId(uid):null;if(u==null||!DBHelper.ROLE_EMPLOYER.equals(u.getRole())||!DBHelper.STATUS_ACTIVE.equals(u.getStatus())||c==null){s.clear();Intent i=new Intent(this,LoginActivity.class);i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(i);finish();return;}companyId=c.getId();RecyclerView rv=findViewById(R.id.rvApplicants);rv.setLayoutManager(new LinearLayoutManager(this));adapter=new ManageApplicantsAdapter(this,rows,new ManageApplicantsAdapter.OnApplicantActionListener(){public void onViewCV(int p){openDetail(p);}public void onAccept(int id){change(id,"Đã chấp nhận");}public void onReject(int id){change(id,"Đã từ chối");}});rv.setAdapter(adapter);MaterialToolbar t=findViewById(R.id.toolbar);t.setNavigationOnClickListener(v->finish());search=findViewById(R.id.etApplicantSearch);if(search!=null)search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){load(s.toString());}public void afterTextChanged(Editable e){}});load("");}
 private void openDetail(int p){if(p<0||p>=rows.size())return;Intent i=new Intent(this,ApplicantDetailActivity.class);i.putExtra("APPLICATION_ID",Integer.parseInt(String.valueOf(rows.get(p).get("id"))));i.putExtra("COMPANY_ID",companyId);startActivity(i);}
 private void change(int id,String s){new AlertDialog.Builder(this).setMessage("Cập nhật trạng thái hồ sơ?").setPositiveButton("Xác nhận",(d,w)->{if(db.updateApplicationStatusForCompany(id,companyId,s))load(search==null?"":search.getText().toString());else Toast.makeText(this,"Không thể cập nhật hồ sơ",Toast.LENGTH_SHORT).show();}).setNegativeButton("Hủy",null).show();}
 private void load(String q){rows.clear();rows.addAll(db.getEmployerApplicants(companyId,q,status));adapter.notifyDataSetChanged();View e=findViewById(R.id.layoutEmpty);e.setVisibility(rows.isEmpty()?View.VISIBLE:View.GONE);}
}
